class AISearchEngine:
    def __init__(self):
        self.exa_api_key = os.environ.get('EXA_API_KEY')
        self.search_results = []

    async def search_exa(self, query, num_results=1000):
        """Exa AI keresés több mint 1000 forrásból"""
        headers = {
            'Authorization': f'Bearer {self.exa_api_key}',
            'Content-Type': 'application/json'
        }

        # Több keresési stratégia kombinálása
        search_strategies = [
            {'query': query, 'type': 'neural', 'num_results': 300},
            {'query': f'"{query}" site:wikipedia.org', 'type': 'keyword', 'num_results': 200},
            {'query': f'{query} filetype:pdf', 'type': 'keyword', 'num_results': 200},
            {'query': f'{query} news', 'type': 'neural', 'num_results': 200},
            {'query': f'{query} research paper', 'type': 'neural', 'num_results': 100}
        ]

        all_results = []

        async with aiohttp.ClientSession() as session:
            for strategy in search_strategies:
                try:
                    payload = {
                        'query': strategy['query'],
                        'type': strategy['type'],
                        'num_results': strategy['num_results'],
                        'include_domains': [],
                        'exclude_domains': [],
                        'start_crawl_date': '2020-01-01',
                        'end_crawl_date': '2025-12-31',
                        'start_published_date': '2020-01-01',
                        'end_published_date': '2025-12-31'
                    }

                    async with session.post(
                        'https://api.exa.ai/search',
                        headers=headers,
                        json=payload
                    ) as response:
                        if response.status == 200:
                            data = await response.json()
                            all_results.extend(data.get('results', []))
                        else:
                            logger.warning(f"Exa API hiba: {response.status}")

                except Exception as e:
                    logger.error(f"Keresési hiba: {e}")

        # Duplikátumok eltávolítása URL alapján
        unique_results = {}
        for result in all_results:
            url = result.get('url', '')
            if url not in unique_results:
                unique_results[url] = result

        self.search_results = list(unique_results.values())
        logger.info(f"Összesen {len(self.search_results)} egyedi forrás találva")
        return self.search_results

    async def get_content_details(self, urls):
        """Részletes tartalom lekérése a találatokhoz"""
        headers = {
            'Authorization': f'Bearer {self.exa_api_key}',
            'Content-Type': 'application/json'
        }

        # Batch-ekben dolgozunk a rate limit miatt
        batch_size = 50
        detailed_results = []

        async with aiohttp.ClientSession() as session:
            for i in range(0, len(urls), batch_size):
                batch_urls = urls[i:i+batch_size]

                try:
                    payload = {
                        'ids': batch_urls,
                        'contents': {
                            'text': True,
                            'highlights': True,
                            'summary': True
                        }
                    }

                    async with session.post(
                        'https://api.exa.ai/contents',
                        headers=headers,
                        json=payload
                    ) as response:
                        if response.status == 200:
                            data = await response.json()
                            detailed_results.extend(data.get('results', []))

                except Exception as e:
                    logger.error(f"Tartalom lekérési hiba: {e}")

        return detailed_results

    def analyze_with_cerebras(self, query, search_results):
        """Cerebras AI elemzés a keresési eredményekről"""
        # Keresési eredmények összefoglalása
        results_summary = ""
        for i, result in enumerate(search_results[:50]):  # Első 50 eredmény
            results_summary += f"{i+1}. {result.get('title', 'Nincs cím')}\n"
            results_summary += f"   URL: {result.get('url', '')}\n"
            results_summary += f"   Összefoglaló: {result.get('text', '')[:200]}...\n\n"

        system_prompt = f"""
        Te egy professzionális AI kutatási asszisztens vagy. A felhasználó keresési kérdésére alapos, átfogó választ kell adnod.

        Keresési kérdés: {query}

        Rendelkezésre álló források száma: {len(search_results)}

        Feladatod:
        1. Elemezd a keresési eredményeket
        2. Adj átfogó, strukturált választ magyar nyelven
        3. Hivatkozz a legfontosabb forrásokra
        4. Emelj ki kulcsfontosságú információkat
        5. Adj gyakorlati tanácsokat, ha releváns

        Keresési eredmények:
        {results_summary}
        """

        try:
            stream = cerebras_client.chat.completions.create(
                messages=[
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": f"Kérlek, adj részletes választ erre a kérdésre: {query}"}
                ],
                model="llama-4-scout-17b-16e-instruct",
                stream=True,
                max_completion_tokens=8192,
                temperature=0.7,
                top_p=0.9
            )

            response_text = ""
            for chunk in stream:
                if chunk.choices[0].delta.content:
                    response_text += chunk.choices[0].delta.content

            return response_text

        except Exception as e:
            logger.error(f"Cerebras elemzési hiba: {e}")
            return "Hiba történt az AI elemzés során."

    def enhance_with_gemini(self, query, cerebras_response):
        """Gemini AI-val való kiegészítés és finomítás"""
        try:
            model = genai.GenerativeModel('gemini-pro')

            prompt = f"""
            Egy AI keresőmotor válaszát szeretném javítani és kiegészíteni.

            Eredeti keresési kérdés: {query}

            Jelenlegi válasz:
            {cerebras_response}

            Kérlek:
            1. Javítsd ki a nyelvtani hibákat
            2. Tedd strukturáltabbá a választ
            3. Adj hozzá további hasznos információkat
            4. Javítsd a magyar nyelvű megfogalmazást
            5. Adj gyakorlati példákat, ha lehetséges

            A válasz legyen professzionális, informatív és könnyen érthető.
            """

            response = model.generate_content(prompt)
            return response.text

        except Exception as e:
            logger.error(f"Gemini kiegészítési hiba: {e}")
            return cerebras_response

# AI keresőmotor példány
search_engine = AISearchEngine()

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/search', methods=['POST'])
async def search():
    try:
        data = request.get_json()
        query = data.get('query', '')

        if not query:
            return jsonify({'error': 'Kérlek, adj meg egy keresési kifejezést!'}), 400

        # 1. Exa AI keresés (1000+ forrás)
        logger.info(f"Keresés indítása: {query}")
        search_results = await search_engine.search_exa(query)

        if len(search_results) < 1000:
            logger.warning(f"Csak {len(search_results)} forrás található, kevesebb mint 1000")

        # 2. Cerebras AI elemzés
        logger.info("Cerebras AI elemzés...")
        cerebras_response = search_engine.analyze_with_cerebras(query, search_results)

        # 3. Gemini AI kiegészítés
        logger.info("Gemini AI kiegészítés...")
        final_response = search_engine.enhance_with_gemini(query, cerebras_response)

        # 4. Válasz összeállítása
        response_data = {
            'query': query,
            'sources_count': len(search_results),
            'response': final_response,
            'top_sources': search_results[:10],  # Top 10 forrás megjelenítése
            'timestamp': datetime.now().isoformat()
        }

        return jsonify(response_data)

    except Exception as e:
        logger.error(f"Keresési hiba: {e}")
        return jsonify({'error': 'Hiba történt a keresés során. Kérlek, próbáld újra!'}), 500

