// Modern JavaScript ES6+ AI Search Engine
class AISearchEngine {
    constructor() {
        this.initializeElements();
        this.bindEvents();
        this.currentQuery = '';
        this.isSearching = false;
    }

    initializeElements() {
        this.searchInput = document.getElementById('searchInput');
        this.searchBtn = document.getElementById('searchBtn');
        this.loadingSection = document.getElementById('loadingSection');
        this.resultsSection = document.getElementById('resultsSection');
        this.loadingStatus = document.getElementById('loadingStatus');
        this.progressBar = document.getElementById('progressBar');
        this.queryTitle = document.getElementById('queryTitle');
        this.sourcesCount = document.getElementById('sourcesCount');
        this.timestamp = document.getElementById('timestamp');
        this.responseContent = document.getElementById('responseContent');
        this.sourcesList = document.getElementById('sourcesList');
        this.newSearchBtn = document.getElementById('newSearchBtn');
        this.suggestionBtns = document.querySelectorAll('.suggestion-btn');
    }

    bindEvents() {
        // Keresés gomb
        this.searchBtn.addEventListener('click', () => this.handleSearch());

        // Enter billentyű a keresőmezőben
        this.searchInput.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') {
                this.handleSearch();
            }
        });

        // Javaslat gombok
        this.suggestionBtns.forEach(btn => {
            btn.addEventListener('click', () => {
                const query = btn.getAttribute('data-query');
                this.searchInput.value = query;
                this.handleSearch();
            });
        });

        // Új keresés gomb
        this.newSearchBtn.addEventListener('click', () => this.resetSearch());

        // Auto-focus a keresőmezőre
        this.searchInput.focus();
    }

    async handleSearch() {
        const query = this.searchInput.value.trim();

        if (!query) {
            this.showError('Kérlek, adj meg egy keresési kifejezést!');
            return;
        }

        if (this.isSearching) {
            return; // Már folyamatban van egy keresés
        }

        this.currentQuery = query;
        this.isSearching = true;
        this.showLoading();

        try {
            const response = await this.performSearch(query);
            this.displayResults(response);
        } catch (error) {
            console.error('Keresési hiba:', error);
            this.showError('Hiba történt a keresés során. Kérlek, próbáld újra!');
        } finally {
            this.isSearching = false;
        }
    }

    async performSearch(query) {
        const loadingSteps = [
            'Források keresése...',
            'AI elemzés indítása...',
            'Cerebras AI feldolgozás...',
            'Gemini AI kiegészítés...',
            'Eredmények összeállítása...'
        ];

        let currentStep = 0;
        const stepInterval = setInterval(() => {
            if (currentStep < loadingSteps.length) {
                this.loadingStatus.textContent = loadingSteps[currentStep];
                this.progressBar.style.width = `${(currentStep + 1) * 20}%`;
                currentStep++;
            }
        }, 800);

        try {
            const response = await fetch('/search', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ query: query })
            });

            clearInterval(stepInterval);

            if (!response.ok) {
                const errorData = await response.json();
                throw new Error(errorData.error || 'Hiba történt a keresés során');
            }

            const data = await response.json();
            return data;

        } catch (error) {
            clearInterval(stepInterval);
            throw error;
        }
    }

    showLoading() {
        this.loadingSection.style.display = 'block';
        this.resultsSection.style.display = 'none';
        this.progressBar.style.width = '0%';

        // Smooth scroll to loading section
        this.loadingSection.scrollIntoView({ 
            behavior: 'smooth',
            block: 'start'
        });
    }

    displayResults(data) {
        this.loadingSection.style.display = 'none';
        this.resultsSection.style.display = 'block';

        // Query info
        this.queryTitle.textContent = data.query;
        this.sourcesCount.textContent = `${data.sources_count.toLocaleString()} forrás elemezve`;
        this.timestamp.textContent = this.formatTimestamp(data.timestamp);

        // AI response
        this.responseContent.innerHTML = this.formatResponse(data.response);

        // Top sources
        this.displaySources(data.top_sources);

        // Smooth scroll to results
        this.resultsSection.scrollIntoView({ 
            behavior: 'smooth',
            block: 'start'
        });

        // Analytics
        this.trackSearch(data.query, data.sources_count);
    }

    formatResponse(response) {
        // Markdown-szerű formázás
        let formatted = response
            .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
            .replace(/\*(.*?)\*/g, '<em>$1</em>')
            .replace(/\n\n/g, '</p><p>')
            .replace(/\n/g, '<br>');

        // Bekezdések hozzáadása
        formatted = '<p>' + formatted + '</p>';

        // Listák formázása
        formatted = formatted.replace(/^\d+\.\s/gm, '<li>');
        formatted = formatted.replace(/^-\s/gm, '<li>');

        return formatted;
    }

    displaySources(sources) {
        this.sourcesList.innerHTML = '';

        sources.forEach((source, index) => {
            const sourceElement = document.createElement('div');
            sourceElement.className = 'source-item';
            sourceElement.style.animationDelay = `${index * 0.1}s`;

            const title = source.title || 'Cím nem elérhető';
            const url = source.url || '#';
            const snippet = source.text ? source.text.substring(0, 200) + '...' : 'Leírás nem elérhető';

            sourceElement.innerHTML = `
                <div class="source-title">${this.escapeHtml(title)}</div>
                <a href="${url}" target="_blank" rel="noopener noreferrer" class="source-url">
                    ${this.formatUrl(url)}
                </a>
                <div class="source-snippet">${this.escapeHtml(snippet)}</div>
            `;

            this.sourcesList.appendChild(sourceElement);
        });
    }

    formatUrl(url) {
        try {
            const urlObj = new URL(url);
            return urlObj.hostname;
        } catch {
            return url;
        }
    }

    formatTimestamp(timestamp) {
        const date = new Date(timestamp);
        return date.toLocaleString('hu-HU', {
            year: 'numeric',
            month: 'long',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        });
    }

    escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }

    showError(message) {
        this.loadingSection.style.display = 'none';

        // Egyszerű alert helyett toast notification
        this.showToast(message, 'error');
    }

    showToast(message, type = 'info') {
        const toast = document.createElement('div');
        toast.className = `toast toast-${type}`;
        toast.textContent = message;

        toast.style.cssText = `
            position: fixed;
            top: 20px;
            right: 20px;
            background: ${type === 'error' ? '#ef4444' : '#10b981'};
            color: white;
            padding: 15px 20px;
            border-radius: 10px;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
            z-index: 1000;
            animation: slideInRight 0.3s ease-out;
        `;

        document.body.appendChild(toast);

        setTimeout(() => {
            toast.style.animation = 'slideOutRight 0.3s ease-out';
            setTimeout(() => {
                document.body.removeChild(toast);
            }, 300);
        }, 3000);
    }

    resetSearch() {
        this.searchInput.value = '';
        this.searchInput.focus();
        this.loadingSection.style.display = 'none';
        this.resultsSection.style.display = 'none';
        this.currentQuery = '';

        // Smooth scroll to top
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    trackSearch(query, sourcesCount) {
        // Analytics tracking
        if (typeof gtag !== 'undefined') {
            gtag('event', 'search', {
                'search_term': query,
                'sources_analyzed': sourcesCount
            });
        }

        console.log(`Keresés: "${query}" - ${sourcesCount} forrás elemezve`);
    }
}

// CSS animációk hozzáadása
